import {
  Auth0Provider as Auth0ReactProvider,
  type AppState,
} from '@auth0/auth0-react';
import type { ReactNode } from 'react';
import { useNavigate } from 'react-router';
import { env } from '../env';

interface Auth0ProviderProps {
  children: ReactNode;
}

export default function Auth0Provider({ children }: Auth0ProviderProps) {
  const navigate = useNavigate();

  const handleRedirectCallback = (appState?: AppState) => {
    navigate(appState?.returnTo || '/profile');
  };

  return (
    <Auth0ReactProvider
      domain={env.VITE_AUTH0_DOMAIN}
      clientId={env.VITE_AUTH0_CLIENT_ID}
      authorizationParams={{
        redirect_uri: window.location.origin,
        audience: env.VITE_AUTH0_AUDIENCE,
      }}
      onRedirectCallback={handleRedirectCallback}
      useRefreshTokens
      cacheLocation="localstorage"
    >
      {children}
    </Auth0ReactProvider>
  );
}

import { Box, CircularProgress } from '@mui/material';
import { useAuth0 } from '@auth0/auth0-react';
import type { ReactNode } from 'react';
import { useEffect } from 'react';

interface AuthGuardProps {
  children: ReactNode;
}

export default function AuthGuard({ children }: AuthGuardProps) {
  const { isAuthenticated, isLoading, loginWithRedirect } = useAuth0();

  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      loginWithRedirect().catch(console.error);
    }
  }, [isAuthenticated, isLoading, loginWithRedirect]);

  if (isLoading) {
    return (
      <Box
        sx={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          minHeight: '50vh',
        }}
      >
        <CircularProgress />
      </Box>
    );
  }

  if (!isAuthenticated) {
    return null;
  }

  return children;
}

import { useAuth0 } from '@auth0/auth0-react';
import { useEffect, useState } from 'react';
import { useError } from '../error/useError';

export function useAuthenticatedUser() {
  const { user, isAuthenticated, isLoading, getAccessTokenSilently } =
    useAuth0();
  const [accessToken, setAccessToken] = useState<string | null>(null);
  const { showError } = useError();

  useEffect(() => {
    if (isAuthenticated && !isLoading) {
      getAccessTokenSilently()
        .then((token) => setAccessToken(token))
        .catch(() => {
          showError(
            'Your session has expired. Please log in again to continue.',
          );
        });
    }
  }, [isAuthenticated, isLoading, getAccessTokenSilently, showError]);

  return {
    user,
    accessToken,
    isAuthenticated,
    isLoading,
  };
}

