import { createEnv } from '@t3-oss/env-core';
import { z } from 'zod';

export const env = createEnv({
  clientPrefix: 'VITE_',
  client: {
    VITE_AUTH0_DOMAIN: z.string().min(1),
    VITE_AUTH0_CLIENT_ID: z.string().min(1),
    VITE_AUTH0_AUDIENCE: z.string().min(1),
    VITE_API_URL: z.string().url().default('http://localhost:8080'),
  },
  runtimeEnv: import.meta.env,
  emptyStringAsUndefined: true,
});

import { useAuth0 } from '@auth0/auth0-react';
import { useEffect, useState } from 'react';
import { useError } from '../error/useError';

export function useAuthenticatedUser() {
  const { user, isAuthenticated, isLoading, getAccessTokenSilently } =
    useAuth0();
  const [accessToken, setAccessToken] = useState<string | null>(null);
  const { showError } = useError();

  useEffect(() => {
    if (isAuthenticated && !isLoading) {
      getAccessTokenSilently()
        .then((token) => setAccessToken(token))
        .catch(() => {
          showError(
            'Your session has expired. Please log in again to continue.',
          );
        });
    }
  }, [isAuthenticated, isLoading, getAccessTokenSilently, showError]);

  return {
    user,
    accessToken,
    isAuthenticated,
    isLoading,
  };
}

import { Avatar, Box, Card, CardContent, Typography } from '@mui/material';
import AuthGuard from '../auth/AuthGuard';
import { useAuthenticatedUser } from '../auth/useAuthenticatedUser';

function ProfileContent() {
  const { user, accessToken } = useAuthenticatedUser();

  const name = user?.name || user?.email || 'Unknown user';
  const email = user?.email || 'No email on file';
  const picture = user?.picture;

  return (
    <Box sx={{ maxWidth: 560, mx: 'auto' }}>
      <Typography variant="h4" component="h1" sx={{ mb: 3 }}>
        Profile
      </Typography>

      <Card variant="outlined">
        <CardContent sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
            <Avatar
              src={picture}
              alt={name}
              sx={{
                width: 64,
                height: 64,
                bgcolor: 'primary.main',
                color: 'primary.contrastText',
              }}
            >
              {name.charAt(0).toUpperCase()}
            </Avatar>
            <Box>
              <Typography variant="h6">{name}</Typography>
              <Typography variant="body2" color="text.secondary">
                {email}
              </Typography>
            </Box>
          </Box>

          {accessToken ? (
            <Box>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                Access token (truncated, demo only)
              </Typography>
              <Typography
                component="code"
                sx={{
                  fontFamily: 'var(--font-mono)',
                  fontSize: '0.75rem',
                  color: 'text.secondary',
                  wordBreak: 'break-all',
                }}
              >
                {truncateToken(accessToken)}
              </Typography>
            </Box>
          ) : null}
        </CardContent>
      </Card>
    </Box>
  );
}

function truncateToken(token: string, maxLength = 80): string {
  if (token.length <= maxLength) {
    return token;
  }
  return `${token.slice(0, maxLength)}…`;
}

export default function ProfilePage() {
  return (
    <AuthGuard>
      <ProfileContent />
    </AuthGuard>
  );
}

